const trust = document.createElement('section'); trust.className = 'trust-section'; trust.id = 'trust'; trust.innerHTML = '<span class="tag" style="color:#8fd3ff">WHY USE XCROW</span><h2>Clear steps. Shared visibility.<br>Better control over a deal.</h2><p>XCROW is designed to give everyone in an escrow room the same transaction status, shared conversation, and a clear path from agreement to settlement.</p><div class="trust-grid"><article class="trust-card"><b>🔒</b><h3>One shared deal room</h3><p>Buyer, seller, and an optional third party work from the same escrow code and status.</p></article><article class="trust-card"><b>📋</b><h3>Visible milestones</h3><p>Both parties can see when an escrow is ready, funded, under review, released, or refunded.</p></article><article class="trust-card"><b>🧾</b><h3>Payment records</h3><p>Confirmed payments retain a transaction record and downloadable receipt for the participants.</p></article><article class="trust-card"><b>🎧</b><h3>Support when needed</h3><p>Either party can invite XCROW Support into the escrow room for dispute assistance.</p></article></div>'; $('.hero').after(trust);
